 }})</option>@endforeach</select><div class="form-text" id="warehouseHelp">Saldo masuk atau keluar hanya diterapkan pada gudang ini. Untuk stok keluar, pilihan tanpa saldo cukup akan dinonaktifkan.</div></div><div class="form-group" id="supplier-stock-group"><label for="supplier_id">Supplier Asal</label><select name="supplier_id" id="supplier_id" class="form-select @error('supplier_id') is-invalid @enderror" aria-describedby="stockSupplierHelp"><option value="">Tanpa Supplier</option>@foreach($suppliers as $supplier)<option value="{{ $supplier->id }}" @selected((string) old('supplier_id') === (string) $supplier->id)>{{ $supplier->kode_supplier }} · {{ $supplier->nama_supplier }}</option>@endforeach</select><div class="form-text" id="stockSupplierHelp">Opsional dan hanya digunakan untuk transaksi barang masuk.</div></div><div class="form-group"><label for="jumlah">Jumlah</label><input type="number" name="jumlah" id="jumlah" class="form-control @error('jumlah') is-invalid @enderror" min="1" value="{{ old('jumlah', request('jumlah')) }}" required></div><div class="form-group"><label for="keterangan">Keterangan</label><input type="text" name="keterangan" id="keterangan" class="form-control @error('keterangan') is-invalid @enderror" maxlength="1000" placeholder="Contoh: Restock atau pemakaian barang" value="{{ old('keterangan', request('prediction_id') ? 'Restock dari prediksi #'.request('prediction_id') : '') }}"></div><div class="d-flex justify-content-end"><x-ui.button href="/barang/{{ $barang->id }}" variant="light" class="me-2">Batal</x-ui.button><x-ui.button type="submit" icon="ti-save" :disabled="$warehouses->isEmpty()">Simpan</x-ui.button></div></form></x-ui.card></div></div>
