@push('scripts')<script>(function(){const type=document.getElementById('jenis');const warehouse=document.getElementById('warehouse_id');const quantity=document.getElementById('jumlah');const supplierGroup=document.getElementById('supplier-stock-group');const supplier=document.getElementById('supplier_id');const balance=document.getElementById('selected-warehouse-stock');function sync(){const outgoing=type.value==='keluar';const needed=Math.max(1,Number(quantity.value)||1);supplierGroup.hidden=outgoing;supplier.disabled=outgoing;if(outgoing)supplier.value='';Array.from(warehouse.options).forEach(function(option){if(!option.value)return;option.disabled=outgoing&&Number(option.dataset.stock)<needed;});if(warehouse.selectedOptions[0]&&warehouse.selectedOptions[0].disabled)warehouse.value='';const option=warehouse.options[warehouse.selectedIndex];balance.textContent=option&&option.value?(option.dataset.stock+' {{ $barang->satuan }}'):'Pilih gudang';}type.addEventListener('change',sync);warehouse.addEventListener('change',sync);quantity.addEventListener('input',sync);sync();}());</script>@endpush
